// Body-weight conversion parity with upstream's convertBodyWeight.
//
// fixtures/bodyweight-vectors.json was generated by running upstream v1.4.1's own function
// (frontend/src/lib/units.js) under node 22 over 2,024 inputs. It is always checked; when the
// upstream source is at hand (UPSTREAM_SRC=<checkout root>), the live upstream function is
// checked against both the vectors and this copy as well.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { convertBodyWeight, LB_PER_KG, toStoredBodyWeight } from '../src/units.js';

const { vectors } = JSON.parse(fs.readFileSync(new URL('./fixtures/bodyweight-vectors.json', import.meta.url), 'utf8'));

test('convertBodyWeight matches upstream on every recorded vector', () => {
  assert.ok(vectors.length > 2000);
  for (const v of vectors) assert.equal(convertBodyWeight(v.value, v.from, v.to), v.out, JSON.stringify(v));
});

test('the factor and the 0.1 step are upstream\'s', () => {
  assert.equal(LB_PER_KG, 2.2046226218);
  assert.equal(convertBodyWeight(80.2, 'kg', 'lb'), 176.8);
  assert.equal(convertBodyWeight(176.8, 'lb', 'kg'), 80.2);
  assert.equal(convertBodyWeight(80.237, 'kg', 'kg'), 80.237, 'same unit: unchanged, as upstream');
  assert.equal(toStoredBodyWeight(80.237, 'kg', 'kg'), 80.2, 'stored at 0.1 even in the same unit');
  assert.equal(toStoredBodyWeight(80.25, 'kg', 'kg'), 80.3);
  assert.equal(toStoredBodyWeight(80.2, 'kg', 'lb'), 176.8);
});

test('live upstream function agrees (when UPSTREAM_SRC is set)', { skip: !process.env.UPSTREAM_SRC && 'UPSTREAM_SRC not set; the recorded vectors above still ran' }, async () => {
  const upstream = await import(pathToFileURL(path.join(process.env.UPSTREAM_SRC, 'frontend/src/lib/units.js')).href);
  for (const v of vectors) {
    assert.equal(upstream.convertBodyWeight(v.value, v.from, v.to), v.out, `vector drifted from upstream: ${JSON.stringify(v)}`);
  }
  for (let x = 0.1; x < 400; x += 0.37) {
    for (const [from, to] of [['kg', 'lb'], ['lb', 'kg'], ['kg', 'kg'], ['lb', 'lb']]) {
      assert.equal(convertBodyWeight(x, from, to), upstream.convertBodyWeight(x, from, to), `${x} ${from}->${to}`);
    }
  }
});
